func (p *physicalFamilyProxy) dialSelected(ctx context.Context, metadata *C.Metadata, selectedIPv6 bool) (C.Conn, error) {
	if ctx.Err() != nil {
		return nil, ctx.Err()
	}
	proxy := p.primary
	if selectedIPv6 {
		proxy = p.alternate
	}
	conn, err := proxy.DialContext(ctx, metadata)
	if ctx.Err() != nil {
		if conn != nil {
			conn.Close()
		}
		return nil, ctx.Err()
	}
	if err != nil && conn != nil {
		conn.Close()
		conn = nil
	}
	return conn, err
